def read(p): return json.loads(Path(p).read_text())
def digest(p): return 'sha256:'+hashlib.sha256(Path(p).read_bytes()).hexdigest()
def binding(p):
 p=Path(p);return {'path':str(p.relative_to(ROOT)),'sha256':digest(p),'bytes':p.stat().st_size}
def write(name,value):
 p=BASE/name;p.parent.mkdir(parents=True,exist_ok=True)
 with p.open('x') as f: f.write(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
 return p
def pointer(j,p):
 for k in p.strip('/').split('/'): j=j[int(k)] if isinstance(j,list) else j[k.replace('~1','/').replace('~0','~')]
 return j
def valuehash(v):return 'sha256:'+hashlib.sha256(json.dumps(v,ensure_ascii=False,sort_keys=True,separators=(',',':')).encode()).hexdigest()

